import json,pathlib,hashlib,collections,subprocess,uuid
ROOT=pathlib.Path.cwd()
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
old=json.loads(pathlib.Path('docs/dev/ci-graph-repairs/locale-topology-conflicts-2026-11-06.json').read_text());xs=json.load(open('/tmp/mannheim-all-contexts.json'));owners={x['data']['landscapeId'] for x in xs};ids={g['id'] for x in xs for g in x['data']['goals']};selected={x['path'] for x in xs};current=[];documents=[]
for p in sorted(pathlib.Path('curricula').rglob('*.json')):
 if 'quality' in p.parts:continue
 try:j=json.loads(p.read_text())
 except:continue
 if not isinstance(j,dict) or not isinstance(j.get('landscapeId'),str) or not isinstance(j.get('goals'),list):continue
 current.append({'path':str(p),'sha256':sha(p),'owner':j['landscapeId']});documents.append((str(p),j))
external=[];allincoming=[]
for p,j in documents:
 for i,g in enumerate(j['goals']):
  for f,rr in [('contains',g.get('contains',[])),('requires',g.get('requires',[])),('examData.coveredGoalIds',(g.get('examData') or {}).get('coveredGoalIds',[]))]:
   for k,r in enumerate(rr):
    if not isinstance(r,str):continue
    gid=r.rsplit(':',1)[-1]
    if gid not in ids:continue
    row={'path':p,'sourceOwner':j['landscapeId'],'sourceGoalId':g['id'],'sourceTitle':g.get('title'),'sourceDescription':g.get('description'),'field':f,'index':k,'reference':r,'targetGoalId':gid}
    allincoming.append(row)
    if p not in selected:external.append(row)
oldmap={f['path']:f['sha256'] for f in old['sourceFiles']};newmap={f['path']:f['sha256'] for f in current}
summary={'observedHead':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'sourceUniverse':current,'sourceUniverseCount':len(current),'serializedGoals':sum(len(j['goals']) for _,j in documents),'baselineInputSha256':sha('docs/dev/ci-graph-repairs/locale-topology-conflicts-2026-11-06.json'),'sourceDifferencesFromOriginalCensus':{'addedPaths':sorted(newmap.keys()-oldmap.keys()),'removedPaths':sorted(oldmap.keys()-newmap.keys()),'changed':[{'path':p,'before':oldmap[p],'current':newmap[p]} for p in sorted(oldmap.keys()&newmap.keys()) if oldmap[p]!=newmap[p]]},'allReferencesToMannheimGoals':allincoming,'referencesFromOutside16Files':external,'pairs':[]}
for a in xs[:8]:
 b=next(x for x in xs if x['data']['landscapeId']==a['data']['landscapeId'] and x['path']!=a['path']);A={g['id']:g for g in a['data']['goals']};B={g['id']:g for g in b['data']['goals']};shared=sorted(A.keys()&B.keys());census=[]
 for x,gs,label in [(a,A,'A'),(b,B,'B')]:
  parents=collections.defaultdict(list)
  for g in gs.values():
   for r in g.get('contains',[]):parents[r].append(g['id'])
  refs=[{'source':g['id'],'field':f,'target':r,'resolvedInGlobalSerializations':[p for p,j in documents if any(z['id']==r for z in j['goals'])]} for g in gs.values() for f in ['contains','requires'] for r in g.get(f,[]) if r not in gs]
  census.append({'label':label,'source':{'path':x['path'],'sha256':x['sha256']},'metadata':{k:v for k,v in x['data'].items() if k!='goals'},'goals':[{**g,'reviewDirectParents':parents[g['id']]} for g in gs.values()],'externalOrUnresolvedWithinFileReferences':refs,'roots':sorted(gs.keys()-parents.keys()),'roleCounts':dict(collections.Counter('cluster' if g.get('contains') else 'atomic' for g in gs.values()))})
 summary['pairs'].append({'module':a['path'].split('_LLB_')[-1].split('.')[0],'owner':a['data']['landscapeId'],'sharedGoalIds':shared,'aOnlyGoalIds':sorted(A.keys()-B.keys()),'bOnlyGoalIds':sorted(B.keys()-A.keys()),'sameIdTextDifferences':[{'goalId':i,'fields':[f for f in ['title','description','titleEn','descriptionEn'] if A[i].get(f)!=B[i].get(f)]} for i in shared if any(A[i].get(f)!=B[i].get(f) for f in ['title','description','titleEn','descriptionEn'])],'sameIdRoleChanges':[i for i in shared if bool(A[i].get('contains'))!=bool(B[i].get('contains'))],'variants':census})
print('universe',len(current),'goals',summary['serializedGoals'],'modified',len(summary['sourceDifferencesFromOriginalCensus']['changed']));print('external',json.dumps(external,ensure_ascii=False,indent=2));print('pairs',[(p['module'],len(p['sharedGoalIds']),len(p['aOnlyGoalIds']),len(p['bOnlyGoalIds'])) for p in summary['pairs']])
pathlib.Path('/tmp/mannheim-technical.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
